// resolveHotspotZone finds the zone a captive-portal request belongs to.
// The customer app forwards the ?zone= query param it received from the
// router's login redirect (see App.vue/usePortalParams.js and the
// zone-embedded login.html generated by ZoneCaptiveLoginHTML) as either a
// query param or a body field named zoneID. Falling back to the first zone
// in the DB preserves behavior for any router still running an
// older-generation script/login.html that doesn't pass a zone yet.
func resolveHotspotZone(c *fiber.Ctx, zoneIDStr string) (*models.Zone, error) {
	var zone models.Zone
	if zoneIDStr == "" {
		zoneIDStr = c.Query("zone_id")
	}
	if zoneIDStr != "" {
		if err := config.DB.First(&zone, zoneIDStr).Error; err == nil {
			return &zone, nil
		}
	}
	if err := config.DB.First(&zone).Error; err != nil {
		return nil, err
	}
	return &zone, nil
}

// HotspotPay handles payment initiation from the captive portal.
func HotspotPay(c *fiber.Ctx) error {
	var body struct {
		Phone  string `json:"phone"`
		PlanID string `json:"plan_id"`
		Mac    string `json:"mac"`
		IP     string `json:"ip"`
		ZoneID string `json:"zone_id"`
	}

	if err := c.BodyParser(&body); err != nil {
		return utils.ErrorResponse(c, "Invalid request body.", "", fiber.StatusBadRequest)
	}

	if body.Phone == "" || body.PlanID == "" {
		return utils.ErrorResponse(c, "phone and plan_id are required.", "", fiber.StatusUnprocessableEntity)
	}

	phone := utils.FormatPhone(body.Phone)

	// The zone must be the one the router sent the device from — never a
	// fallback (that could charge for another ISP's WiFi).
	zonePtr := zoneByID(body.ZoneID)
	if zonePtr == nil {
		zonePtr = zoneByID(c.Query("zone_id"))
	}
	if zonePtr == nil {
		return utils.ErrorResponse(c, "Open this page from the WiFi login screen to pay.", "", fiber.StatusBadRequest)
	}
	zone := *zonePtr
	// Don't take money for WiFi that can't connect anyone right now.
	if ok, msg := services.ZoneAcceptingPayments(zone.ID); !ok {
		return zoneOfflineResponse(c, msg)
	}

	// Map plan_id to package details
	var price float64
	var speedDown, speedUp int
	var name string

	switch strings.ToLower(body.PlanID) {
	case "basic":
		price = 20
		speedDown = 2048
		speedUp = 1024
		name = "Basic"
	case "premium":
		price = 50
		speedDown = 10240
		speedUp = 5120
		name = "Premium"
	default: // standard
		price = 30
		speedDown = 5120
		speedUp = 2048
		name = "Standard"
	}

	// Find or create package in DB
	var pkg models.Package
	if err := config.DB.Where("price = ? AND type = ? AND zone_id = ?", price, "hotspot", zone.ID).First(&pkg).Error; err != nil {
		pkg = models.Package{
			ZoneID:            zone.ID,
			Name:              name,
			Type:              "hotspot",
			Price:             price,
			BillingCycle:      "daily",
			SpeedDownloadKbps: speedDown,
			SpeedUploadKbps:   speedUp,
			Status:            "active",
		}
		if err := config.DB.Create(&pkg).Error; err != nil {
			return utils.ErrorResponse(c, err.Error(), "Failed to create package.", fiber.StatusInternalServerError)
		}
	}

	// Auto-generate voucher
	voucher, err := voucherSvcGlobal.Generate(zone.ID, pkg.ID, "single_use", 1)
	if err != nil {
		return utils.ErrorResponse(c, err.Error(), "Failed to prepare voucher.", fiber.StatusInternalServerError)
	}

	var customerID *uint
	if cust, ok := services.CustomerByPhoneForZone(zone.ID, phone); ok {
		customerID = &cust.ID
	} else if cust, ok := services.CustomerByDeviceForZone(zone.ID, body.Mac); ok {
		customerID = &cust.ID
	}

	// Create pending payment record
	payment := models.Payment{
		CustomerID: customerID,
		VoucherID:  &voucher.ID,
		ZoneID:     zone.ID,
		PackageID:  &pkg.ID,
		Phone:      phone,
		Amount:     pkg.Price,
		Currency:   "KES",
		Method:     "mpesa",
		Status:     "pending",
		MacAddress: body.Mac,
		IpAddress:  body.IP,
	}

	if err := config.DB.Create(&payment).Error; err != nil {
		return utils.ErrorResponse(c, err.Error(), "Failed to create payment record.", fiber.StatusInternalServerError)
	}

	ref := fmt.Sprintf("Vouch%d", voucher.ID)
	description := "WiFi"
	if pkg.Name != "" {
		description = pkg.Name
	}

	stkResp, err := mpesaSvcGlobal.InitiateSTKPush(zone.ID, phone, pkg.Price, ref, description)
	if err != nil {
		reason := err.Error()
		config.DB.Model(&payment).Updates(map[string]interface{}{
			"status":        "failed",
			"status_reason": reason,
		})
		return utils.ErrorResponse(c, err.Error(), "M-Pesa API error.", fiber.StatusInternalServerError)
	}

	if stkResp.Status == "success" {
		config.DB.Model(&payment).Update("mpesa_transaction_id", stkResp.CheckoutRequestID)

		// Simulate callback in mock/sandbox mode
		if stkResp.IsMock {
			mpesaSvcGlobal.SimulateCallback(stkResp.CheckoutRequestID, pkg.Price, phone)
		}

		return c.JSON(fiber.Map{
			"reference": stkResp.CheckoutRequestID,
			"message":   "STK Push initiated successfully.",
		})
	}

	reason := "Failed to initiate M-Pesa STK Push payment."
	config.DB.Model(&payment).Updates(map[string]interface{}{
		"status":        "failed",
		"status_reason": reason,
	})
	return utils.ErrorResponse(c, reason, "", fiber.StatusBadRequest)
}

// HotspotStatus checks payment status for polling.
func HotspotStatus(c *fiber.Ctx) error {
	ref := c.Params("reference")
	if ref == "" {
		return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{"status": "failed", "message": "Reference is required"})
	}

	// The reference is the M-Pesa CheckoutRequestID handed only to the payer
	// who started the push. It must be the *only* accepted key: this endpoint
	// signs the payer in (session cookie + token) once the payment completes,
	// so accepting a guessable identifier — the sequential payment id it used
	// to fall back to — let anyone walk 1,2,3… and take over every paying
	// customer's session.
	var payment models.Payment
	if len(ref) < 8 {
		return c.Status(fiber.StatusNotFound).JSON(fiber.Map{"status": "failed", "message": "Payment record not found"})
	}
	if err := config.DB.Where("mpesa_transaction_id = ?", ref).First(&payment).Error; err != nil {
		return c.Status(fiber.StatusNotFound).JSON(fiber.Map{"status": "failed", "message": "Payment record not found"})
	}

	buildPaidResponse := func(p *models.Payment) (fiber.Map, bool) {
		resp := fiber.Map{"status": "paid"}
		if p.PackageID != nil {
			var pkg models.Package
			if config.DB.First(&pkg, *p.PackageID).Error == nil {
				resp["plan_name"] = pkg.Name
				resp["speed"] = fmt.Sprintf("%d Mbps", pkg.SpeedDownloadKbps/1024)
			}
		}
		if p.CustomerID == nil || *p.CustomerID == 0 {
			// The payment completes before the customer is attached; keep the
			// portal polling for a little while.
			if time.Since(p.UpdatedAt) < 2*time.Minute {
				return nil, false
			}
			resp["message"] = "Payment received. Sign in with your phone number to connect."
			return resp, true
		}
		token, _ := middleware.GenerateCustomerToken(*p.CustomerID)
		middleware.SetAuthCookie(c, middleware.CustomerCookieName, token)
		resp["token"] = token
		resp["customer_id"] = *p.CustomerID

		// The device that paid gets its own router login. The reference is
		// the proof: only the payer's session holds the CheckoutRequestID.
		// Never a shared pkg-<id> / free login.
		if _, ok := services.NormalizeMAC(p.MacAddress); ok {
			rl, _, err := grantRouterLogin(*p.CustomerID, p.MacAddress, zoneByID(fmt.Sprint(p.ZoneID)), "paid", true)
			if err == nil {
				resp["router_login"] = rl
			} else if errors.Is(err, services.ErrNoActivePlan) && time.Since(p.UpdatedAt) < 2*time.Minute {
				return nil, false // plan still being activated
			} else {
				log.Printf("[Hotspot] payment %d: no router login: %v", p.ID, err)
				resp["message"] = "Payment received. Sign in with your phone number to connect."
			}
		} else {
			resp["message"] = "Payment received. Connect to the WiFi and sign in with your phone number."
		}
		return resp, true
	}

	if payment.Status == "completed" {
		if resp, ok := buildPaidResponse(&payment); ok {
			return c.JSON(resp)
		}
		return c.JSON(fiber.Map{"status": "pending"})
	} else if payment.Status == "failed" {
		msg := "Payment failed"
		if payment.StatusReason != nil {
			msg = *payment.StatusReason
		}
		return c.JSON(fiber.Map{"status": "failed", "message": msg})
	}

	// Reconcile status with M-Pesa query API as a fallback if the transaction is pending
	if payment.Status == "pending" && mpesaSvcGlobal != nil {
		newStatus, err := mpesaSvcGlobal.QueryAndUpdateSTKStatus(&payment)
		if err == nil {
			if newStatus == "completed" {
				config.DB.First(&payment, payment.ID)
				if resp, ok := buildPaidResponse(&payment); ok {
					return c.JSON(resp)
				}
				return c.JSON(fiber.Map{"status": "pending"})
			} else if newStatus == "failed" {
				msg := "Payment failed"
				if payment.StatusReason != nil {
					msg = *payment.StatusReason
				}
				return c.JSON(fiber.Map{"status": "failed", "message": msg})
			}
		} else {
			log.Printf("[M-Pesa] Error querying STK status: %v", err)
		}
	}

	return c.JSON(fiber.Map{"status": "pending"})
}

// sessionCustomer finds whose session a portal request is asking about,
// from proof only: the device token (bound to this MAC) or a customer
// session cookie.
func sessionCustomer(c *fiber.Ctx, mac, deviceToken string) (*models.Customer, *models.HotspotCredential) {
	if tok := deviceTokenFrom(c, deviceToken); tok != "" {
		if cred, err := services.CredentialByDeviceToken(tok); err == nil {
			if m, ok := services.NormalizeMAC(mac); !ok || m == cred.MacAddress {
				var cust models.Customer
				if config.DB.Preload("Package").First(&cust, cred.CustomerID).Error == nil {
					return &cust, cred
				}
			}
		}
	}
	if claims := middleware.OptionalCustomerClaims(c); claims != nil && claims.CustomerID > 0 {
		var cust models.Customer
		if config.DB.Preload("Package").First(&cust, claims.CustomerID).Error == nil {
			return &cust, nil
		}
	}
	return nil, nil
}

// HotspotSession returns the active plan for this device. It needs the
// device token or a customer session: a MAC alone tells nothing.
func HotspotSession(c *fiber.Ctx) error {
	cust, _ := sessionCustomer(c, c.Query("mac"), "")
	now := time.Now()
	if cust == nil || cust.Package == nil || cust.Status != "active" || cust.ExpiresAt == nil || !cust.ExpiresAt.After(now) {
		return c.JSON(fiber.Map{"active": false})
	}
	return c.JSON(fiber.Map{
		"active":     true,
		"plan_name":  cust.Package.Name,
		"speed":      fmt.Sprintf("%.0f Mbps", float64(cust.Package.SpeedDownloadKbps)/1024),
		"time_left":  int64(time.Until(*cust.ExpiresAt).Seconds()),
		"expires_at": *cust.ExpiresAt,
	})
}

// HotspotLogout ends this device's own router session. It needs proof that
// the caller is that device (device token, or a customer session holding a
// login for this MAC) — otherwise anyone could kick anyone off.
func HotspotLogout(c *fiber.Ctx) error {
	var body struct {
		Mac         string `json:"mac"`
		ZoneID      string `json:"zone_id"`
		DeviceToken string `json:"device_token"`
	}
	if err := c.BodyParser(&body); err != nil || body.Mac == "" {
		return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{"success": false, "error": "mac is required"})
	}
	mac, ok := services.NormalizeMAC(body.Mac)
	if !ok {
		return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{"success": false, "error": "mac is required"})
	}
	zone := zoneByID(body.ZoneID)
	if zone == nil {
		return c.Status(fiber.StatusBadRequest).JSON(fiber.Map{"success": false, "error": "zone_id is required"})
	}

	allowed := false
	if tok := deviceTokenFrom(c, body.DeviceToken); tok != "" {
		if cred, err := services.CredentialByDeviceToken(tok); err == nil && cred.MacAddress == mac && cred.OrganizationID == zone.OrganizationID {
			allowed = true
		}
	}
	if !allowed {
		if claims := middleware.OptionalCustomerClaims(c); claims != nil && claims.CustomerID > 0 &&
			services.CustomerHoldsMAC(zone.OrganizationID, claims.CustomerID, mac) {
			allowed = true
		}
	}
	if !allowed {
		return c.Status(fiber.StatusUnauthorized).JSON(fiber.Map{"success": false, "code": "proof_required", "error": "Sign in on this device to log it out."})
	}

	svc := routerSvc()
	if svc == nil {
		return c.JSON(fiber.Map{"success": true})
	}
	if err := svc.DisconnectClient(zone, mac); err != nil {
		log.Printf("[Hotspot] Failed to disconnect client %s: %v", mac, err)
		if config.Config.AppEnv == "local" {
			log.Printf("[Hotspot] Dev mode: bypassing disconnect failure.")
			return c.JSON(fiber.Map{"success": true})
		}
		return c.Status(fiber.StatusInternalServerError).JSON(fiber.Map{"success": false, "error": "Could not reach the router. Try again in a moment."})
	}

	return c.JSON(fiber.Map{"success": true})
}
